import { appearance } from './appearance'

function channels(color) {
	if (typeof color !== 'string') return null
	if (/^#[\da-f]{6}$/i.test(color))
		return color
			.slice(1)
			.match(/../g)
			.map((v) => parseInt(v, 16))
	if (/^#[\da-f]{3}$/i.test(color))
		return color
			.slice(1)
			.split('')
			.map((v) => parseInt(v + v, 16))
	const match = color.match(/^rgba?\(\s*(\d+)[, ]+\s*(\d+)[, ]+\s*(\d+)/)
	return match ? match.slice(1).map(Number) : null
}
function luminance(values) {
	return values
		.map((v) => v / 255)
		.map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4))
		.reduce((sum, v, i) => sum + v * [0.2126, 0.7152, 0.0722][i], 0)
}

/** Keep the hue of dynamic chart/status labels, adjusting only their contrast.
 * Chart values and series fills are untouched. Called from template styles so
 * a palette switch updates existing charts without refetching any data. */
export function themeInk(color) {
	const theme = appearance.value.theme
	if (theme.id === 'default') return color
	const original = channels(color)
	if (!original) return color
	const background = luminance(channels(theme.surface))
	const target = theme.mode === 'dark' ? 255 : 0
	let result = original
	for (let step = 0; step <= 20; step++) {
		result = original.map((v) => Math.round(v + ((target - v) * step) / 20))
		const foreground = luminance(result)
		if (
			(Math.max(background, foreground) + 0.05) /
				(Math.min(background, foreground) + 0.05) >=
			4.5
		)
			break
	}
	return `rgb(${result.join(', ')})`
}
